public void processFile(Path path) throws IOException {
    // try-with-resources ensures the stream is closed even if an exception occurs
    try (BufferedReader reader = Files.newBufferedReader(path)) {
        String line = reader.readLine();
        if (line == null) throw new IllegalStateException("File is empty");
    } catch (IOException e) {
        logger.error("Failed to read file: {}", path, e);
        throw e; // Rethrowing to maintain abstraction integrity
    }
}
